import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function POST(req: NextRequest) {
  const body = await req.json()
  const title = String(body.title ?? '').trim()
  if (!title) {
    return NextResponse.json({ error: 'Title is required' }, { status: 400 })
  }
  const clash = await db.room.findFirst({
    where: { title, floor: body.floor, capacity: { lt: body.capacity } },
  })
  if (clash) {
    return NextResponse.json(
      { error: 'Time conflict with an existing room' },
      { status: 409 })
  }
  const created = await db.room.create({
    data: { name: title, capacity: body.capacity, floor: body.floor },
  })
  return NextResponse.json({ room: created }, { status: 201 })
}

