import { NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function POST(req: NextRequest) {
  const body = await req.json()
  const roomId = String(body.roomId ?? '').trim()
  if (!roomId) {
    return NextResponse.json({ error: 'RoomId is required' }, { status: 400 })
  }
  const clash = await db.reservation.findFirst({
    where: { roomId, start: { lt: body.start }, end: { gt: body.start } },
  })
  if (clash) {
    return NextResponse.json(
      { error: 'Time conflict with an existing reservation' },
      { status: 409 })
  }
  const created = await db.reservation.create({
    data: { roomId, title: body.title, organizer: body.organizer, start: body.start, end: body.end },
  })
  return NextResponse.json({ reservation: created }, { status: 201 })
}

