export async function GET(req: NextRequest) {
  const rooms = await db.room.findMany()
  const filters = req.nextUrl.searchParams
  const q = filters.get('q')?.toLowerCase()
  const minCapacity = parseInt(filters.get('minCapacity') ?? '0')
  const date = filters.get('date')?.toLowerCase()
  const roomsByDate = await db.room.findMany({
    where: { start: { lt: date + 'T00:00' }, end: { gt: date + 'T00:00' } },
    include: { reservations: true },
  })
  const filteredRooms = rooms.filter(room => {
    if (q) {
      const title = room.title.toLowerCase()
      const organizer = room.organizer.toLowerCase()
      const start = new Date(room.start)
      const end = new Date(room.end)
      const dateRange = new Date(date + 'T00:00').getTime() <= start.getTime() && new Date(date + 'T00:00').getTime() >= end.getTime()
      const titleRange = title.toLowerCase().includes(q.toLowerCase())
      const organizerRange = organizer.toLowerCase().includes(q.toLowerCase())
      const startRange = new Date(date + 'T00:00').getTime() <= start.getTime()
      const endRange = new Date(date + 'T00:00').getTime() >= end.getTime()
      return titleRange && organizerRange && startRange && endRange && dateRange
    }
    if (minCapacity > 0) {
      return room.capacity >= minCapacity
    }
    return true
  })
  const roomsByTitle = rooms.filter(room => {
    if (q) {
      const title = room.title.toLowerCase()
      const start = new Date(room.start)
      const end = new Date(room.end)
      const dateRange = new Date(date + 'T00:00').getTime() <= start.getTime() && new Date(date + 'T00:00').getTime() >= end.getTime()
      return dateRange
    }
    if (minCapacity > 0) {
      return room.capacity >= minCapacity
    }
    return true
  })
  return NextResponse.json({
    rooms: roomsByTitle.concat(roomsByDate),
    total: rooms.length,
  })
}

